// 13 — Capture Completed Output
const ctx = $input.first().json;
const job = ctx.job || {};
const result = job.result || {};
const url = result.video_url || Object.values(result).find((v) => typeof v === 'string' && /^https:\/\//.test(v)) || null;
const ok = typeof url === 'string' && url.startsWith('https://');
const completed_at = job.completed_at || new Date().toISOString();
const submittedMs = new Date(ctx.submission.submitted_at).getTime();
const metadata = {
  ltx_job_id: ctx.submission.ltx_job_id, ltx_created_at: job.created_at || ctx.submission.ltx_created_at, ltx_completed_at: job.completed_at || null,
  generation_seconds: Math.round((new Date(completed_at).getTime() - submittedMs) / 1000),
  poll_attempts: ctx.poll.attempts, result_keys: Object.keys(result),
  request: ctx.ltx_request.body.image_uri && ctx.ltx_request.body.image_uri.startsWith('data:')
    ? { ...ctx.ltx_request.body, image_uri: '[data-uri omitted]' } : ctx.ltx_request.body,
  estimated_cost_usd: ctx.ltx.estimated_cost_usd, cost_basis: `${ctx.ltx.duration}s × $${ctx.ltx.price_per_second_usd}/s (docs.ltx.io/pricing, ${ctx.ltx.pricing_verified})`,
  output_url_note: 'LTX output URLs expire. Download/archive the clip promptly.',
  warnings: ctx.warnings,
};
return [{ json: {
  ...ctx, output_ok: ok, output_url: url, completed_at, output_metadata: metadata,
  error_status: ok ? null : 'OUTPUT_RETRIEVAL_FAILED',
  errors: ok ? [] : [{ field: 'ltx_job.result', message: 'Job completed but no HTTPS video URL was found. Keys: ' + Object.keys(result).join(', ') }],
} }];

// Builds archive_ctx from the captured LTX output, then the shared Cloudinary preparation logic runs.
const __c = $('13 — Capture Completed Output').first().json;
const __ctx = { ...__c, archive_ctx: { shot_id: __c.manifest.shot_id, version: __c.manifest.version, generation_key: __c.manifest.generation_key, season_id: __c.manifest.season_id, episode_id: __c.manifest.episode_id, scene_id: __c.manifest.scene_id, generation_type: __c.manifest.generation_type, ltx_job_id: __c.submission.ltx_job_id, source_url: __c.output_url, force_regenerate: __c.manifest.force_regenerate === true, test: __c.manifest.episode_id === 'TEST' } };
const __ARC_INPUT = __ctx;
// Prepare Archive Request — shared by the pipeline (13A2) and the archive-repair path (X05).
// Input: $json.archive_ctx = { shot_id, version, generation_key, season_id, episode_id, scene_id, generation_type,
//                              ltx_job_id, source_url, force_regenerate, test }
// Deterministic Cloudinary identity. Every version is a separate, never-overwritten asset.
const c = (typeof __ARC_INPUT !== 'undefined') ? __ARC_INPUT : $input.first().json;
const a = c.archive_ctx;
const pad3 = (n) => String(n).padStart(3, '0');
const num = (s, prefix) => { const m = String(s || '').match(new RegExp('^' + prefix + '(\\d+)$', 'i')); return m ? m[1].padStart(2, '0') : String(s || 'x').toLowerCase().replace(/[^a-z0-9]+/g, '-'); };
const root = a.test ? 'the-sumerian/_pipeline-tests' : 'the-sumerian';
const folder = [root, 'season-' + num(a.season_id, 'S'), 'episode-' + num(a.episode_id, 'E'), 'scene-' + num(a.scene_id, 'SC'), a.shot_id, 'v' + pad3(a.version)].join('/');
let asset = `${a.shot_id}_v${pad3(a.version)}`;
// An exceptional force_regenerate rerun gets its own asset so the earlier archived output is never replaced.
if (a.force_regenerate && a.ltx_job_id) asset += '_rerun-' + String(a.ltx_job_id).replace(/[^A-Za-z0-9]/g, '').slice(0, 8);
const public_id = `${folder}/${asset}`;
const esc = (v) => String(v == null ? '' : v).replace(/([=|\\])/g, '\\$1');
const context = [
  ['shot_id', a.shot_id], ['version', a.version], ['generation_key', a.generation_key], ['ltx_job_id', a.ltx_job_id],
  ['generation_type', a.generation_type], ['project', 'THE SUMERIAN'], ['pipeline', 'LTX PRODUCTION PIPELINE v1.1'],
].map(([k, v]) => `${k}=${esc(v)}`).join('|');
const tags = ['the-sumerian', a.shot_id, `${a.shot_id}_v${pad3(a.version)}`, 'v' + pad3(a.version),
  'season-' + num(a.season_id, 'S'), 'episode-' + num(a.episode_id, 'E'), 'scene-' + num(a.scene_id, 'SC'),
  String(a.generation_type || '').toLowerCase().replace(/_/g, '-'), 'ltx', a.test ? 'pipeline-test' : 'production'].filter(Boolean).join(',');

return [{ json: { ...c, archive: {
  provider: 'CLOUDINARY', attempt: 0, max_attempts: 3, retry_wait_seconds: 10,
  expected_public_id: public_id, asset_folder: folder,
  params: { file: a.source_url, public_id, asset_folder: folder, overwrite: 'false', tags, context },
  history: [],
} } }];

// Count Archive Attempt — loop head of the bounded archive retry (max 3 Cloudinary attempts; never an LTX call).
const c = $input.first().json;
return [{ json: { ...c, archive: { ...c.archive, attempt: (c.archive.attempt || 0) + 1, attempt_started_at: new Date().toISOString() } } }];

// Verify Archive Result — classifies the Cloudinary upload response.
// ARCHIVED: 200 + https secure_url + expected public_id. RETRY: clearly transient (network, timeout, 429/420, 5xx) and attempts left.
// FAILED: anything else, or attempts exhausted. Never triggers an LTX generation.
const st = $('13A3 — Count Archive Attempt').first().json;
const r = $input.first().json || {};
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
let b = r.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { /* keep text */ } }
const a = st.archive;
const now = new Date().toISOString();
const errMsg = b && b.error ? (b.error.message || JSON.stringify(b.error)) : (r.error ? (r.error.message || String(r.error)) : null);
const clip = (s) => String(s == null ? '' : s).replace(/(api_key|api_secret|signature)=[^&\s]+/gi, '$1=[redacted]').slice(0, 500);

let decision, detail = null, result = null;
if (status === 200 && b && typeof b.secure_url === 'string' && b.secure_url.startsWith('https://')) {
  if (b.public_id !== a.expected_public_id) {
    decision = 'FAILED'; detail = `Cloudinary stored public_id "${b.public_id}" instead of "${a.expected_public_id}".`;
  } else {
    decision = 'ARCHIVED';
    result = { archive_url: b.secure_url, archive_public_id: b.public_id, archive_asset_id: b.asset_id || '', archive_version: b.version || null,
      resource_type: b.resource_type || null, format: b.format || null, bytes: b.bytes || null, duration: b.duration || null,
      width: b.width || null, height: b.height || null, existing: b.existing === true, created_at: b.created_at || null, asset_folder: b.asset_folder || a.asset_folder,
      tags: Array.isArray(b.tags) ? b.tags : [], context: b.context && b.context.custom ? b.context.custom : (b.context || null) };
  }
} else {
  const transient = status === null || status === 408 || status === 420 || status === 429 || (status >= 500 && status <= 599);
  detail = `Cloudinary ${status === null ? 'no response (network/timeout)' : 'HTTP ' + status}${errMsg ? ': ' + clip(errMsg) : ''}`;
  decision = transient && a.attempt < a.max_attempts ? 'RETRY' : 'FAILED';
  if (decision === 'FAILED' && transient) detail += ` (gave up after ${a.attempt} attempts)`;
}

const history = [...(a.history || []), { attempt: a.attempt, at: now, http_status: status, decision, detail }];
return [{ json: { ...st, archive: { ...a, history, decision, detail, result, finished_at: decision === 'RETRY' ? null : now } } }];

// The clip was generated (and paid for) but could not be archived. No new LTX render is triggered.
const c = $('13C — Verify Archive Result').first().json;
return [{ json: { result: 'ARCHIVE_FAILED', error_status: 'OUTPUT_ARCHIVE_FAILED', shot_id: c.manifest.shot_id, version: c.manifest.version, generation_key: c.manifest.generation_key, ltx_job_id: c.submission.ltx_job_id, generation_status: 'COMPLETED', approval_status: 'ARCHIVE_FAILED', source_output_url: c.output_url, archive_provider: 'CLOUDINARY', archive_attempts: c.archive.attempt, archive_history: c.archive.history, next_step: 'Repair the archive with the Archive Repair form (or POST /webhook/sumerian/archive-retry) while the temporary LTX URL is still valid. Do not regenerate.' } }];

// Final structured result (execution output; also persisted in the Production Library). Prefer archive_url.
const c = $('13C — Verify Archive Result').first().json;
const r = c.archive.result;
return [{ json: { result: 'REVIEW_REQUIRED', shot_id: c.manifest.shot_id, version: c.manifest.version, generation_key: c.manifest.generation_key, generation_type: c.manifest.generation_type, ltx_job_id: c.submission.ltx_job_id, generation_status: 'COMPLETED', approval_status: 'REVIEW_REQUIRED', archive_url: r.archive_url, archive_provider: 'CLOUDINARY', archive_public_id: r.archive_public_id, archive_asset_id: r.archive_asset_id, source_output_url: c.output_url, estimated_cost_usd: c.ltx.estimated_cost_usd, submitted_at: c.submission.submitted_at, completed_at: c.completed_at, archived_at: c.archive.finished_at, metadata: c.output_metadata, next_step: 'Human review required (Shot Review form): APPROVE / REJECT / REQUEST_REVISION. Review the archive_url.' } }];
